    for i in range(1, N):
        # If the absolute difference between two adjacent terms is 1, terminate the procedure
        if A[i] - A[i+1] == 1:
            return A[i]
        # If the absolute difference between two adjacent terms is not 1, insert the pair of adjacent terms nearest to the beginning of A
        if A[i] < A[i+1]:
            A[i+1] = A[i] + A[i+2]
        elif A[i] > A[i+1]:
            A[i+1] = A[i] - A[i+2]
        # Return to step 1
        return A

