    # Initialize dp table
    dp = [[0] * (len(S) + 1) for _ in range(len(S) + 1)]

    # Initialize dp table for S
    dp[S] = 0
    for i in range(len(S)):
        dp[S[i]] = dp[S[i-1]] + dp[S[i-2]]

    # Initialize dp table for T
    dp[T] = 0
    for i in range(len(T) + 1):
        dp[T[i]] = dp[T[i-1]] + dp[T[i-2]]

    # Check if it is possible to win with cheating
    if dp[S[i]] == dp[T[i]] and dp[S[i]] > dp[T[i]] and dp[S[i]] < dp[T[i]]:
        return True
    else:
        return False

